import pandas as pd
import numpy as np

# Load all available experiments
dfs = {}
for eid in [1, 2, 3, 4, 6]:
    try:
        dfs[f"exp{eid}"] = pd.read_csv(f"experiment_{eid}_csv")
        print(f"\n=== Experiment {eid} ===")
        print(f"Columns: {list(dfs[f'exp{eid}'].columns)}")
        print(f"Shape: {dfs[f'exp{eid}'].shape}")
        print(dfs[f"exp{eid}"].describe().round(3))
    except Exception as e:
        print(f"Error loading experiment {eid}: {e}")

# Look at correlations with HarvestBiomass
for name, df in dfs.items():
    if "HarvestBiomass" in df.columns:
        print(f"\n{name} correlations with HarvestBiomass:")
        if len(df.columns) > 1:
            for col in df.columns:
                if col != "HarvestBiomass":
                    try:
                        corr = df[col].corr(df["HarvestBiomass"])
                        print(f"  {col}: r={corr:.3f}")
                    except:
                        pass
